genericcontrol.script:
-- Pill styles, named for what they mean rather than their
-- colour, so a ruleset asks for "positive" and the art decides
-- how that looks. The label uses one font throughout and takes
-- its colour from the style, since the neutral art is light
-- while the other two are dark.
local _tStyles = {
	negative = { sFrame = "cc_tag_negative", sColor = "FFFFFFFF" },
	positive = { sFrame = "cc_tag_positive", sColor = "FFFFFFFF" },
	neutral = { sFrame = "cc_tag_neutral", sColor = "FF1A1A1A" },
};
local _wLabel = nil;
function setText(sText, sStyle)
	if (sText or "") == "" then
		setVisible(false);
		-- collapse so empty chip rows don't inflate the card
		setAnchoredHeight(0);
		setAnchoredWidth(0);
		return;
	end
	local tStyle = _tStyles[sStyle or ""] or _tStyles["neutral"];
	setFrame(tStyle.sFrame);
	if not _wLabel then
		_wLabel = addTextWidget({ font = "cc_chip", text = sText, position = "center" });
	else
		_wLabel.setText(sText);
	end
	_wLabel.setColor(tStyle.sColor);
	local nTextWidth = _wLabel.getSize();
	setAnchoredWidth((nTextWidth or 24) + 12);
	setAnchoredHeight(14);
	setVisible(true);
end
